BEGIN;
SET LOCAL request.jwt.claims='{"role":"service_role"}';
DO $verify$
DECLARE ca uuid:=gen_random_uuid();cb uuid:=gen_random_uuid();actor uuid:=gen_random_uuid();owner uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();super_id uuid:=gen_random_uuid();intent uuid:=gen_random_uuid();all_intent uuid:=gen_random_uuid();r jsonb;before_balance integer;after_balance integer;
BEGIN
 INSERT INTO public.campuses(id,name,slug) VALUES(ca,'[AUDIT rollback] Expiry A','audit-expiry-'||ca),(cb,'[AUDIT rollback] Expiry B','audit-expiry-'||cb);
 INSERT INTO auth.users(id,email,raw_user_meta_data) VALUES(actor,'audit-expiry-'||actor||'@example.invalid','{"full_name":"[AUDIT rollback] Expiry admin"}'),(owner,'audit-expiry-'||owner||'@example.invalid','{"full_name":"[AUDIT rollback] Expiry target"}'),(outsider,'audit-expiry-'||outsider||'@example.invalid','{"full_name":"[AUDIT rollback] Expiry other"}'),(super_id,'audit-expiry-'||super_id||'@example.invalid','{"full_name":"[AUDIT rollback] Expiry super"}');
 UPDATE public.profiles SET campus_id=ca,role='admin' WHERE id=actor;
 UPDATE public.profiles SET campus_id=ca,role='student' WHERE id=owner;
 UPDATE public.profiles SET campus_id=cb,role='student' WHERE id=outsider;
 UPDATE public.profiles SET campus_id=cb,role='super_admin' WHERE id=super_id;
 PERFORM public.record_hp_transaction_atomic(owner,100,'earn','active','admin_grant','admin_grant',gen_random_uuid(),actor,'[AUDIT rollback] Initial HP',ca);
 SELECT hp_balance INTO before_balance FROM public.profiles WHERE id=owner;
 r:=public.hg_admin_expire_hp(actor,owner,50,before_balance,'[AUDIT rollback] Partial expiry',intent);
 IF NOT coalesce((r->>'success')::boolean,false) OR (r->>'expired')::integer<>50 OR (SELECT hp_balance FROM public.profiles WHERE id=owner)<>before_balance-50 THEN RAISE EXCEPTION 'partial expiry failed';END IF;
 r:=public.hg_admin_expire_hp(actor,owner,50,before_balance,'[AUDIT rollback] Partial expiry',intent);
 IF NOT coalesce((r->>'replayed')::boolean,false) OR (SELECT hp_balance FROM public.profiles WHERE id=owner)<>before_balance-50 THEN RAISE EXCEPTION 'partial expiry replay deducted twice';END IF;
 r:=public.hg_admin_expire_hp(actor,owner,51,before_balance,'[AUDIT rollback] Partial expiry',intent);
 IF r->>'error' IS DISTINCT FROM 'expiry_conflict' THEN RAISE EXCEPTION 'changed expiry accepted';END IF;
 PERFORM public.record_hp_transaction_atomic(owner,20,'earn','active','admin_grant','admin_grant',gen_random_uuid(),actor,'[AUDIT rollback] Later HP',ca);
 r:=public.hg_admin_expire_hp(actor,owner,50,before_balance,'[AUDIT rollback] Partial expiry',intent);
 IF NOT coalesce((r->>'replayed')::boolean,false) OR (SELECT hp_balance FROM public.profiles WHERE id=owner)<>before_balance-30 THEN RAISE EXCEPTION 'expiry replay consumed later earning';END IF;
 r:=public.hg_admin_expire_hp(actor,owner,10,before_balance,'[AUDIT rollback] Stale preview',gen_random_uuid());
 IF r->>'error' IS DISTINCT FROM 'expiry_balance_changed' THEN RAISE EXCEPTION 'stale preview accepted';END IF;
 SELECT hp_balance INTO after_balance FROM public.profiles WHERE id=owner;
 r:=public.hg_admin_expire_hp(actor,owner,NULL,after_balance,'[AUDIT rollback] All active',all_intent);
 IF NOT coalesce((r->>'success')::boolean,false) OR (SELECT hp_balance FROM public.profiles WHERE id=owner)<>0 THEN RAISE EXCEPTION 'all-active expiry failed';END IF;
 r:=public.hg_admin_expire_hp(actor,owner,NULL,after_balance,'[AUDIT rollback] All active',all_intent);
 IF NOT coalesce((r->>'replayed')::boolean,false) THEN RAISE EXCEPTION 'null-mode replay failed';END IF;
 PERFORM public.record_hp_transaction_atomic(owner,10,'earn','active','admin_grant','admin_grant',gen_random_uuid(),actor,'[AUDIT rollback] After all expiry',ca);
 r:=public.hg_admin_expire_hp(actor,owner,NULL,after_balance,'[AUDIT rollback] All active',all_intent);
 IF NOT coalesce((r->>'replayed')::boolean,false) OR (SELECT hp_balance FROM public.profiles WHERE id=owner)<>10 THEN RAISE EXCEPTION 'all-active replay consumed later earning';END IF;
 r:=public.hg_admin_expire_hp(actor,outsider,NULL,0,'[AUDIT rollback] Foreign',gen_random_uuid());IF r->>'error' IS DISTINCT FROM 'expiry_forbidden' THEN RAISE EXCEPTION 'foreign expiry accepted';END IF;
 r:=public.hg_admin_expire_hp(owner,owner,1,10,'[AUDIT rollback] Student actor',gen_random_uuid());IF r->>'error' IS DISTINCT FROM 'expiry_forbidden' THEN RAISE EXCEPTION 'student expiry accepted';END IF;
 r:=public.hg_admin_expire_hp(super_id,owner,5,10,'[AUDIT rollback] Global actor',gen_random_uuid());IF NOT coalesce((r->>'success')::boolean,false) THEN RAISE EXCEPTION 'super expiry failed';END IF;
 UPDATE public.profiles SET is_active=false WHERE id=actor;
 r:=public.hg_admin_expire_hp(actor,owner,1,5,'[AUDIT rollback] Inactive actor',gen_random_uuid());IF r->>'error' IS DISTINCT FROM 'expiry_forbidden' THEN RAISE EXCEPTION 'inactive actor accepted';END IF;
 IF (SELECT count(*) FROM public.hp_transactions WHERE user_id=owner AND reference_type='admin_expiry')<>3 OR NOT EXISTS(SELECT 1 FROM public.hp_transactions WHERE reference_id=all_intent AND type='expire' AND metadata->'requested_amount'='null'::jsonb AND issued_by_admin_id=actor) THEN RAISE EXCEPTION 'expiry ledger/intent metadata mismatch';END IF;
 IF has_function_privilege('anon','public.hg_admin_expire_hp(uuid,uuid,integer,integer,text,uuid)','execute') OR has_function_privilege('authenticated','public.hg_admin_expire_hp(uuid,uuid,integer,integer,text,uuid)','execute') OR NOT has_function_privilege('service_role','public.hg_admin_expire_hp(uuid,uuid,integer,integer,text,uuid)','execute') THEN RAISE EXCEPTION 'expiry routine grants incorrect';END IF;
END $verify$;
ROLLBACK;
SELECT 'PASS: fresh rollback expiry actors; partial/all-mode exact replay, later earnings preserved, stale previews/changed payloads denied, campus/student/inactive restrictions, super-admin access, private grants and existing ledger metadata' AS evidence;
